commands:
{ nft -a list chain inet f2b-table f2b-chain | sed -nE 's/.*@<addr_set>\s+.*\s+\#\s*(handle\s+[0-9]+)$/\1/p'; } | while read -r hdl; do
nft delete rule inet f2b-table f2b-chain $hdl; done
nft delete set inet f2b-table <addr_set>
{ nft list table inet f2b-table | grep -qE '^\s+set\s+'; } || {
nft delete table inet f2b-table
}

firewall-cmd --direct --remove-rule <family> filter INPUT_direct 0 -p tcp -m multiport --dports 1:65535 -m set --match-set <ipmset> src -j REJECT --reject-with <rejecttype>
ipset flush <ipmset>
ipset destroy <ipmset> 2>/dev/null || { sleep 1; ipset destroy <ipmset>; }
